export const galleryPageSources: Record<string, string> = {
  "/components/accordion": "<script setup lang=\"ts\">\nimport { Accordion, AccordionPanel, CollapsablePanel, Message, Panel } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst activeSingle = ref([\"runtime\"]);\nconst activeMultiple = ref([\"memory\", \"network\"]);\nconst collapsed = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Accordion</h2></template>\n        <Accordion v-model=\"activeSingle\" class=\"accordion-surface\">\n          <AccordionPanel name=\"runtime\" header=\"Runtime\">\n            Java path, launch arguments, and environment variables.\n          </AccordionPanel>\n          <AccordionPanel name=\"network\" header=\"Network\">\n            Ports, address binding, proxy, and query visibility.\n          </AccordionPanel>\n          <AccordionPanel name=\"danger\" header=\"Danger Zone\" disabled>\n            Disabled panels keep their context without accepting input.\n          </AccordionPanel>\n        </Accordion>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>多面板</h2></template>\n        <div class=\"accordion-stack\">\n          <Accordion v-model=\"activeMultiple\" multiple class=\"accordion-surface\">\n            <AccordionPanel name=\"memory\" header=\"Memory\">\n              Allocate a predictable heap range for the selected server profile.\n            </AccordionPanel>\n            <AccordionPanel name=\"network\" header=\"Network\">\n              Keep public and daemon-only ports visually separated.\n            </AccordionPanel>\n            <AccordionPanel name=\"backup\" header=\"Backup\">\n              Scheduled snapshots can be opened together with runtime settings.\n            </AccordionPanel>\n          </Accordion>\n\n          <CollapsablePanel v-model:collapsed=\"collapsed\" header=\"Standalone Collapsible\" shadow=\"never\">\n            <Message color=\"help\" title=\"Composable primitive\">\n              Use CollapsablePanel when a single area needs disclosure without group state.\n            </Message>\n          </CollapsablePanel>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.accordion-stack {\n  display: grid;\n  gap: 14px;\n}\n\n.accordion-surface {\n  overflow: hidden;\n  border: 1px solid var(--mcsl-border-color-base);\n  border-radius: var(--mcsl-border-radius-sm);\n  background: var(--mcsl-bg-color-overlay);\n}\n</style>\n",
  "/components/avatar": "<script setup lang=\"ts\">\nimport { Avatar, Badge, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"avatar-row\">\n          <Avatar text=\"MF\" :size=\"32\" />\n          <Avatar text=\"WS\" />\n          <Avatar text=\"OP\" :size=\"56\" />\n          <Badge value=\"3\" color=\"success\">\n            <Avatar text=\"AD\" />\n          </Badge>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"avatar-list\">\n          <div class=\"avatar-item\"><Avatar text=\"MF\" /><span>MCSL Future</span></div>\n          <div class=\"avatar-item\"><Avatar text=\"EU\" /><span>Paper EU-1</span></div>\n          <div class=\"avatar-item\"><Avatar text=\"DV\" /><span>Development</span></div>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.avatar-row,\n.avatar-list {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: center;\n}\n\n.avatar-list {\n  flex-direction: column;\n  align-items: stretch;\n}\n\n.avatar-item {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  color: var(--mcsl-text-color-regular);\n}\n</style>\n",
  "/components/breadcrumbs": "<script setup lang=\"ts\">\nimport { Breadcrumbs, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst baseCrumbs = [\n  { label: \"MCSL Future\", icon: \"fas fa-cube\" },\n  { label: \"Instances\" },\n  { label: \"Paper EU-1\" },\n];\n\nconst linkedCrumbs = [\n  { label: \"Gallery\", link: \"/components/buttons\" },\n  { label: \"Navigation\", link: \"/components/navigation\" },\n  { label: \"Breadcrumbs\" },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"crumb-stack\">\n          <Breadcrumbs :items=\"baseCrumbs\" />\n          <Breadcrumbs :items=\"linkedCrumbs\" seperator=\">\" />\n          <Breadcrumbs :items=\"baseCrumbs\" seperator=\"·\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <Breadcrumbs :items=\"linkedCrumbs\" />\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.crumb-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
  "/components/buttons": "<script setup lang=\"ts\">\nimport { Badge, Button, ButtonGroup, Panel, SplitButton } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst menu = [\n  { label: \"Duplicate\", icon: \"fas fa-copy\" },\n  { label: \"Export\", icon: \"fas fa-arrow-up-from-bracket\" },\n  { label: \"Archive\", icon: \"fas fa-box-archive\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header>\n          <div class=\"doc-heading\">\n            <h2>基础</h2>\n          </div>\n        </template>\n\n        <div class=\"button-layout\">\n          <div class=\"button-row\">\n            <Button type=\"primary\" color=\"primary\" icon=\"fas fa-check\">\n              Primary\n            </Button>\n            <Button icon=\"fas fa-sliders\">Default</Button>\n            <Button type=\"dashed\" icon=\"fas fa-plus\">Dashed</Button>\n            <Button type=\"text\" icon=\"fas fa-ellipsis\">Text</Button>\n          </div>\n\n          <div class=\"button-row\">\n            <Button color=\"success\" icon=\"fas fa-circle-check\">Success</Button>\n            <Button color=\"warning\" icon=\"fas fa-triangle-exclamation\">\n              Warning\n            </Button>\n            <Button color=\"danger\" icon=\"fas fa-trash\">Danger</Button>\n            <Button disabled icon=\"fas fa-ban\">Disabled</Button>\n          </div>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n\n        <div class=\"button-layout\">\n          <section class=\"button-demo-block\">\n            <h3>按钮组</h3>\n            <ButtonGroup>\n              <Button type=\"primary\" color=\"primary\">Start</Button>\n              <Button>Restart</Button>\n              <Button>Stop</Button>\n              <Button type=\"text\" icon=\"fas fa-gear\" squared />\n            </ButtonGroup>\n          </section>\n\n          <section class=\"button-demo-block\">\n            <h3>分裂按钮</h3>\n            <SplitButton color=\"primary\" type=\"primary\" :dropdown-menu=\"menu\">\n              Deploy\n            </SplitButton>\n          </section>\n\n          <section class=\"button-demo-block\">\n            <h3>图标按钮</h3>\n            <div class=\"button-row button-row--compact\">\n              <Button icon=\"fas fa-rotate-right\" squared />\n              <Button icon=\"fas fa-download\" squared />\n              <Button icon=\"fas fa-arrow-up-right-from-square\" squared />\n              <Button icon=\"fas fa-xmark\" color=\"danger\" squared />\n            </div>\n          </section>\n\n          <section class=\"button-demo-block\">\n            <h3>加载中</h3>\n            <div class=\"button-row\">\n              <Button loading type=\"primary\" color=\"primary\">Saving</Button>\n              <Button loading loading-icon-pos=\"left\">Checking</Button>\n            </div>\n          </section>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.doc-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.button-layout {\n  display: grid;\n  gap: 18px;\n}\n\n.button-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 10px;\n}\n\n.button-row--compact {\n  gap: 8px;\n}\n\n.button-demo-block {\n  display: grid;\n  gap: 10px;\n}\n\n.button-demo-block h3 {\n  margin: 0;\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n  font-weight: 600;\n}\n</style>\n",
  "/components/checkbox": "<script setup lang=\"ts\">\nimport { Checkbox, Panel } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst enabled = ref(true);\nconst mixed = ref<boolean | null>(null);\nconst snapshots = ref(true);\nconst backups = ref(false);\nconst inherited = ref<boolean | null>(null);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"state-grid\">\n          <Checkbox v-model=\"enabled\">Checked</Checkbox>\n          <Checkbox v-model=\"backups\">Unchecked</Checkbox>\n          <Checkbox v-model=\"mixed\" color=\"help\">Mixed</Checkbox>\n          <Checkbox v-model=\"enabled\" disabled>Disabled checked</Checkbox>\n          <Checkbox disabled>Disabled</Checkbox>\n          <Checkbox invalid>Invalid</Checkbox>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"policy-list\">\n          <Checkbox v-model=\"snapshots\">Allow snapshot builds</Checkbox>\n          <Checkbox v-model=\"backups\" color=\"success\">Run scheduled backups</Checkbox>\n          <Checkbox v-model=\"inherited\" color=\"help\">Inherit parent policy</Checkbox>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.state-grid,\n.policy-list {\n  display: grid;\n  gap: 12px;\n  align-items: start;\n}\n\n.state-grid {\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n\n@media (max-width: 720px) {\n  .state-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/code": "<script setup lang=\"ts\">\nimport { Code, Message, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\nimport { galleryCodeHighlighter } from \"../components/galleryCodeHighlighter\";\n\nconst vueExample = `<script setup lang=\"ts\">\nimport { Button, Code } from \"@mcsl/ui\";\n\nconst snippet = \"const status = 'running';\";\n` + \"</scr\" + `ipt>\n\n<template>\n  <Code :code=\"snippet\" language=\"typescript\" />\n  <Button type=\"primary\">Deploy</Button>\n</template>`;\n\nconst tsExample = `type InstanceStatus = \"running\" | \"stopped\";\n\nexport function formatStatus(status: InstanceStatus) {\n  return status === \"running\" ? \"Online\" : \"Offline\";\n}`;\n\nconst plainExample = `MCSL UI Code component\n- Does not bundle highlight.js\n- Accepts an external hljs-compatible highlighter\n- Falls back to escaped plain text`;\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Code</h2></template>\n        <div class=\"code-stack\">\n          <Code\n            :code=\"vueExample\"\n            language=\"xml\"\n            :hljs=\"galleryCodeHighlighter\"\n            line-numbers\n          />\n          <Code :code=\"plainExample\" language=\"plaintext\" max-height=\"12rem\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>外部高亮器</h2></template>\n        <div class=\"code-stack\">\n          <Message color=\"help\" title=\"No bundled highlighter\">\n            Code only receives an hljs-compatible object from the application.\n          </Message>\n          <Code\n            :code=\"tsExample\"\n            language=\"typescript\"\n            :hljs=\"galleryCodeHighlighter\"\n            line-numbers\n          />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.code-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
  "/components/combobox": "<script setup lang=\"ts\">\nimport { AutoComplete, Combobox, Message, Panel, Tag } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst command = ref(\"restart\");\nconst region = ref(\"sg\");\n\nconst commands = [\n  { label: \"Restart server\", value: \"restart\", icon: \"fas fa-rotate\" },\n  { label: \"Create backup\", value: \"backup\", icon: \"fas fa-box-archive\" },\n  { label: \"Open console\", value: \"console\", icon: \"fas fa-terminal\" },\n  { label: \"Stop instance\", value: \"stop\", icon: \"fas fa-power-off\", disabled: true },\n];\n\nconst regions = [\n  { label: \"Singapore\", value: \"sg\", icon: \"fas fa-location-dot\" },\n  { label: \"Frankfurt\", value: \"de\", icon: \"fas fa-location-dot\" },\n  { label: \"Los Angeles\", value: \"us\", icon: \"fas fa-location-dot\" },\n  { label: \"Tokyo\", value: \"jp\", icon: \"fas fa-location-dot\" },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Autocomplete</h2></template>\n        <div class=\"combo-grid\">\n          <label>\n            <span>Command</span>\n            <AutoComplete v-model=\"command\" :options=\"commands\" placeholder=\"Type a command\" />\n          </label>\n          <label>\n            <span>Region</span>\n            <Combobox v-model=\"region\" :options=\"regions\" placeholder=\"Select region\" />\n          </label>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>绑定值</h2></template>\n        <div class=\"combo-stack\">\n          <Message color=\"help\" title=\"Autocomplete keeps custom text\">\n            {{ command }}\n          </Message>\n          <div class=\"tag-row\">\n            <Tag color=\"primary\">Region: {{ region }}</Tag>\n          </div>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.combo-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\nlabel,\n.combo-stack {\n  display: grid;\n  gap: 8px;\n}\n\nlabel > span {\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n  font-weight: 650;\n}\n\n.tag-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n@media (max-width: 720px) {\n  .combo-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/compositions": "<script setup lang=\"ts\">\nimport {\n  Button,\n  Card,\n  Message,\n  MeterGroup,\n  NavTabs,\n  Panel,\n  Tag,\n} from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst qualities = [\n  \"Calmer surfaces\",\n  \"Smaller radii\",\n  \"Softer shadows\",\n  \"Clear hierarchy\",\n];\n\nconst tabs = [\n  { label: \"Overview\", icon: \"fas fa-gauge\" },\n  { label: \"Console\", icon: \"fas fa-terminal\" },\n  { label: \"Backups\", icon: \"fas fa-clock-rotate-left\" },\n];\n\nconst meter = {\n  length: 100,\n  values: [\n    { label: \"CPU\", length: 18, type: \"success\" },\n    { label: \"RAM\", length: 42, type: \"primary\" },\n    { label: \"Disk\", length: 64, type: \"warning\" },\n  ],\n};\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"composition\">\n          <div class=\"composition-main\">\n            <h3>Server Overview</h3>\n            <p>\n              Brand color guides orientation while spacing, typography, and surface hierarchy do most of the work.\n            </p>\n          </div>\n          <div class=\"composition-rail\">\n            <Tag v-for=\"quality in qualities\" :key=\"quality\">{{ quality }}</Tag>\n          </div>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"instance-shell\">\n          <div class=\"instance-header\">\n            <div>\n              <h3>Paper EU-1</h3>\n              <div class=\"tag-row\">\n                <Tag color=\"success\">Online</Tag>\n                <Tag color=\"primary\">Java 21</Tag>\n                <Tag color=\"help\">Paper</Tag>\n              </div>\n            </div>\n            <Button type=\"primary\" color=\"primary\" icon=\"fas fa-terminal\">Console</Button>\n          </div>\n          <NavTabs :tabs=\"tabs\" />\n          <Card title=\"Runtime\" description=\"Current resource allocation and process health.\">\n            <div class=\"card-stack\">\n              <MeterGroup :meter=\"meter\" />\n              <Message title=\"Stable\" color=\"success\">\n                CPU, memory, and disk usage are inside the expected range.\n              </Message>\n            </div>\n          </Card>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.composition {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 220px;\n  gap: 20px;\n}\n\n.composition-main h3,\n.instance-header h3 {\n  margin: 0;\n  font-weight: 600;\n}\n\n.composition-main p {\n  color: var(--mcsl-text-color-regular);\n  line-height: 1.7;\n}\n\n.composition-rail,\n.tag-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  align-content: start;\n}\n\n.instance-shell,\n.card-stack {\n  display: grid;\n  gap: 16px;\n}\n\n.instance-header {\n  display: flex;\n  justify-content: space-between;\n  gap: 16px;\n  align-items: start;\n}\n\n@media (max-width: 980px) {\n  .composition,\n  .instance-header {\n    grid-template-columns: 1fr;\n  }\n\n  .instance-header {\n    flex-direction: column;\n  }\n}\n</style>\n",
  "/components/confirm-dialog": "<script setup lang=\"ts\">\nimport { Button, ConfirmDialog, Panel } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst deleteVisible = ref(false);\nconst restartVisible = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"overlay-row\">\n          <Button color=\"warning\" @click=\"restartVisible = true\">Restart</Button>\n          <Button color=\"danger\" type=\"primary\" @click=\"deleteVisible = true\">Delete</Button>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <Button color=\"danger\" type=\"primary\" icon=\"fas fa-trash\" @click=\"deleteVisible = true\">\n          Delete Instance\n        </Button>\n        <ConfirmDialog\n          v-model:visible=\"deleteVisible\"\n          title=\"Delete instance?\"\n          description=\"This removes the instance record from the launcher. Server files are not deleted automatically.\"\n          confirm-text=\"Delete\"\n          cancel-text=\"Keep\"\n        />\n        <ConfirmDialog\n          v-model:visible=\"restartVisible\"\n          title=\"Restart instance?\"\n          description=\"Players will be disconnected while the process restarts.\"\n          color=\"warning\"\n          confirm-text=\"Restart\"\n          cancel-text=\"Cancel\"\n        />\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n</style>\n",
  "/components/contextmenu": "<script setup lang=\"ts\">\nimport { Contextmenu, Panel, Tag } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst target = ref<HTMLElement | null>(null);\nconst menu = [\n  { label: \"Rename\", icon: \"fas fa-pen\" },\n  { label: \"Duplicate\", icon: \"fas fa-copy\" },\n  { label: \"Delete\", icon: \"fas fa-trash\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"context-target context-target--small\">\n          <Tag color=\"help\">Right click</Tag>\n          <span>Scoped menu target</span>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div ref=\"target\" class=\"context-target\">\n          <Tag color=\"primary\">Instance</Tag>\n          <span>Right click this area</span>\n        </div>\n        <Contextmenu :parent=\"target as any\" :menu=\"menu\" />\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.context-target {\n  min-height: 140px;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  border: 1px dashed color-mix(in srgb, var(--mcsl-border-color-base) 86%, transparent);\n  border-radius: var(--mcsl-border-radius-sm);\n  color: var(--mcsl-text-color-secondary);\n  background: color-mix(in srgb, var(--mcsl-bg-color-overlay) 94%, transparent);\n}\n\n.context-target--small {\n  min-height: 92px;\n}\n</style>\n",
  "/components/copyable-text": "<script setup lang=\"ts\">\nimport { CopyableText, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"copy-stack\">\n          <CopyableText size=\"small\">mcsl-ui</CopyableText>\n          <CopyableText>paper-1.21.1-43.jar</CopyableText>\n          <CopyableText size=\"large\">ws://127.0.0.1:25567/daemon</CopyableText>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <CopyableText>MCSL-UI</CopyableText>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.copy-stack {\n  display: grid;\n  gap: 10px;\n  justify-items: start;\n}\n</style>\n",
  "/components/data-table": "<script setup lang=\"ts\">\nimport { Button, DataTable, Panel, Tag } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst selectedKeys = ref<string[]>([\"paper-eu\"]);\nconst sortBy = ref(\"players\");\nconst sortOrder = ref<\"asc\" | \"desc\" | null>(\"desc\");\n\nconst columns = [\n  { key: \"name\", title: \"Name\", sortable: true, width: \"minmax(180px, 1.2fr)\" },\n  { key: \"status\", title: \"Status\", sortable: true, width: \"120px\" },\n  { key: \"version\", title: \"Version\", width: \"120px\" },\n  { key: \"players\", title: \"Players\", sortable: true, align: \"right\" as const, width: \"110px\" },\n];\n\nconst rows = [\n  { id: \"paper-eu\", name: \"Paper EU-1\", status: \"Online\", version: \"1.21.5\", players: 12 },\n  { id: \"forge-us\", name: \"Forge US-2\", status: \"Installing\", version: \"1.20.1\", players: 0 },\n  { id: \"proxy-sg\", name: \"Velocity SG\", status: \"Online\", version: \"3.4.0\", players: 48 },\n  { id: \"fabric-cn\", name: \"Fabric CN-Dev\", status: \"Offline\", version: \"1.21.4\", players: 0 },\n];\n\nfunction statusColor(status: unknown) {\n  if (status === \"Online\") return \"success\";\n  if (status === \"Installing\") return \"warning\";\n  return \"surface\";\n}\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Data Table</h2></template>\n        <DataTable\n          v-model:selected-keys=\"selectedKeys\"\n          v-model:sort-by=\"sortBy\"\n          v-model:sort-order=\"sortOrder\"\n          :columns=\"columns\"\n          :rows=\"rows\"\n          selectable\n        >\n          <template #cell-status=\"{ value }\">\n            <Tag :color=\"statusColor(value)\" size=\"small\">{{ value }}</Tag>\n          </template>\n          <template #actions>\n            <Button size=\"small\" type=\"text\">Open</Button>\n          </template>\n        </DataTable>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>States</h2></template>\n        <div class=\"datatable-stack\">\n          <DataTable :columns=\"columns\" :rows=\"[]\" />\n          <DataTable :columns=\"columns\" :rows=\"rows.slice(0, 2)\" loading />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.datatable-stack {\n  display: grid;\n  gap: 16px;\n}\n</style>\n",
  "/components/date-time": "<script setup lang=\"ts\">\nimport { Calendar, DatePicker, Message, Panel, TimePicker } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst date = ref(\"2026-06-10\");\nconst time = ref(\"21:30\");\nconst maintenanceDate = ref(\"\");\nconst maintenanceTime = ref(\"\");\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Date & Time</h2></template>\n        <div class=\"date-grid\">\n          <label>\n            <span>Deployment date</span>\n            <DatePicker v-model=\"date\" min=\"2026-01-01\" max=\"2026-12-31\" />\n          </label>\n          <label>\n            <span>Restart time</span>\n            <TimePicker v-model=\"time\" min=\"00:00\" max=\"23:59\" />\n          </label>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Maintenance Window</h2></template>\n        <div class=\"date-stack\">\n          <Calendar v-model=\"maintenanceDate\" min=\"2026-01-01\" max=\"2026-12-31\" />\n          <div class=\"date-grid\">\n            <label>\n              <span>Date</span>\n              <DatePicker v-model=\"maintenanceDate\" placeholder=\"Pick date\" clearable />\n            </label>\n            <label>\n              <span>Time</span>\n              <TimePicker v-model=\"maintenanceTime\" :step=\"300\" clearable />\n            </label>\n          </div>\n          <Message color=\"help\" title=\"Selected window\">\n            {{ maintenanceDate || \"No date\" }} {{ maintenanceTime || \"No time\" }}\n          </Message>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.date-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.date-stack,\nlabel {\n  display: grid;\n  gap: 8px;\n}\n\nlabel > span {\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n  font-weight: 650;\n}\n\n@media (max-width: 720px) {\n  .date-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/display": "<script setup lang=\"ts\">\nimport {\n  Avatar,\n  CopyableText,\n  Empty,\n  Message,\n  Panel,\n  Result,\n  Skeleton,\n  Table,\n  Tag,\n} from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst columns = [\"Name\", \"Status\", \"Version\"];\nconst rows = [\n  [\"Paper EU-1\", \"Running\", \"1.21.1\"],\n  [\"Fabric Dev\", \"Stopped\", \"1.20.4\"],\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"display-grid\">\n          <Panel size=\"small\">\n            <template #header><h4>Identity</h4></template>\n            <div class=\"inline-row\">\n              <Avatar text=\"MF\" />\n              <Tag color=\"primary\">Primary Tag</Tag>\n              <Tag color=\"success\">Healthy</Tag>\n            </div>\n          </Panel>\n          <Panel size=\"small\">\n            <template #header><h4>Text</h4></template>\n            <CopyableText>mcsl-ui</CopyableText>\n          </Panel>\n          <Panel size=\"small\" class=\"display-grid__wide\">\n            <template #header><h4>Empty</h4></template>\n            <Empty title=\"No resources yet\" description=\"Display components should communicate state with calm hierarchy.\" />\n          </Panel>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"display-stack\">\n          <Message title=\"Heads up\" color=\"warning\">\n            This is a lightweight message surface for inline guidance.\n          </Message>\n          <Result title=\"Deployment completed\" description=\"Use result states for larger success or failure summaries.\" status=\"success\" />\n          <Table :columns=\"columns\" :rows=\"rows\" />\n          <Skeleton :lines=\"4\" height=\"14px\" />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.display-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.display-grid__wide {\n  grid-column: 1 / -1;\n}\n\n.display-stack {\n  display: grid;\n  gap: 16px;\n}\n\n.inline-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: center;\n}\n\n@media (max-width: 860px) {\n  .display-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/divider": "<script setup lang=\"ts\">\nimport { Divider, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"divider-stack\">\n          <Divider spacing=\"xs\" />\n          <Divider spacing=\"sm\" variant=\"dashed\">Runtime</Divider>\n          <Divider spacing=\"sm\" variant=\"dotted\" text-pos=\"start\">Advanced</Divider>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"divider-demo\">\n          <p>Instance settings</p>\n          <Divider spacing=\"md\">Network</Divider>\n          <p>Port, address, and proxy configuration</p>\n          <Divider spacing=\"md\" text-pos=\"end\">Danger Zone</Divider>\n          <p>Destructive operations stay visually separated.</p>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.divider-stack,\n.divider-demo {\n  display: grid;\n  gap: 6px;\n}\n\np {\n  margin: 0;\n  color: var(--mcsl-text-color-regular);\n}\n</style>\n",
  "/components/drawer": "<script setup lang=\"ts\">\nimport { Button, Drawer, Message, Panel, Tag } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst rightVisible = ref(false);\nconst bottomVisible = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"overlay-row\">\n          <Button type=\"primary\" color=\"primary\" @click=\"rightVisible = true\">Right Drawer</Button>\n          <Button @click=\"bottomVisible = true\">Bottom Drawer</Button>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <Button type=\"primary\" color=\"primary\" icon=\"fas fa-sidebar\" @click=\"rightVisible = true\">\n          Open Drawer\n        </Button>\n        <Drawer v-model:visible=\"rightVisible\" title=\"Instance Details\">\n          <div class=\"drawer-stack\">\n            <Message title=\"Paper EU-1\" color=\"success\" variant=\"outlined\">\n              Running on Java 21 with 12 active players.\n            </Message>\n            <div class=\"tag-row\">\n              <Tag color=\"primary\">Paper</Tag>\n              <Tag color=\"success\">Online</Tag>\n              <Tag color=\"help\">4 GB</Tag>\n            </div>\n          </div>\n          <template #footer=\"{ close }\">\n            <Button @click=\"close\">Close</Button>\n            <Button type=\"primary\" color=\"primary\">Open Console</Button>\n          </template>\n        </Drawer>\n        <Drawer v-model:visible=\"bottomVisible\" title=\"Task Queue\" placement=\"bottom\">\n          <Message title=\"Backup queued\" color=\"help\">The next scheduled backup starts after upload.</Message>\n        </Drawer>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row,\n.tag-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  align-items: center;\n}\n\n.drawer-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
  "/components/dropdown": "<script setup lang=\"ts\">\nimport { Button, ButtonGroup, DropdownMenu, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst menu = [\n  { label: \"Open settings\", icon: \"fas fa-gear\" },\n  { label: \"Duplicate instance\", icon: \"fas fa-copy\" },\n  { label: \"Archive\", icon: \"fas fa-box-archive\", disabled: true },\n];\n\nconst groupedMenu = [\n  {\n    group: \"Instance\",\n    items: [\n      { label: \"Start\", icon: \"fas fa-play\" },\n      { label: \"Restart\", icon: \"fas fa-rotate-right\" },\n    ],\n  },\n  {\n    group: \"Danger\",\n    items: [{ label: \"Delete\", icon: \"fas fa-trash\", color: \"danger\" }],\n  },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"overlay-row\">\n          <DropdownMenu :menu=\"menu\">\n            <template #triggerer=\"{ toggle }\">\n              <Button icon=\"fas fa-ellipsis\" @click=\"toggle\">Default</Button>\n            </template>\n          </DropdownMenu>\n          <DropdownMenu :menu=\"groupedMenu\" default-pos=\"top\">\n            <template #triggerer=\"{ toggle }\">\n              <Button icon=\"fas fa-arrow-up\" @click=\"toggle\">Top</Button>\n            </template>\n          </DropdownMenu>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <ButtonGroup>\n          <Button type=\"primary\" color=\"primary\">Start</Button>\n          <DropdownMenu :menu=\"groupedMenu\">\n            <template #triggerer=\"{ toggle }\">\n              <Button icon=\"fas fa-angle-down\" squared @click=\"toggle\" />\n            </template>\n          </DropdownMenu>\n        </ButtonGroup>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: center;\n}\n</style>\n",
  "/components/editor": "<script setup lang=\"ts\">\nimport { CodeEditor, CopyableText, Panel } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst value = ref(`{\n  \"name\": \"Future Paper EU-1\",\n  \"runtime\": \"java-21\",\n  \"core\": \"paper-1.21.1-43.jar\",\n  \"memory\": 4096\n}`);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"editor-meta\">\n          <CopyableText>daemon_instance.json</CopyableText>\n          <CopyableText>UTF-8</CopyableText>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"editor-wrap\">\n          <CodeEditor v-model=\"value\" default-lang=\"json\" />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.editor-meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.editor-wrap {\n  min-height: 360px;\n}\n</style>\n",
  "/components/empty": "<script setup lang=\"ts\">\nimport { Button, Empty, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"empty-grid\">\n          <Empty title=\"No running instances\" description=\"Start or import an instance to continue.\" />\n          <Empty title=\"No backups\" description=\"Create a backup schedule before production launch.\" icon=\"fas fa-clock-rotate-left\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <Empty\n          title=\"No running instances\"\n          description=\"Create a new instance or import an existing configuration.\"\n        >\n          <Button type=\"primary\" color=\"primary\" icon=\"fas fa-plus\">Create Instance</Button>\n        </Empty>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.empty-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n@media (max-width: 860px) {\n  .empty-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/feedback": "<script setup lang=\"ts\">\nimport { Empty, Message, MeterGroup, Panel, Result, Skeleton } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst healthyMeter = {\n  length: 100,\n  values: [\n    { label: \"CPU\", length: 18, type: \"success\" },\n    { label: \"RAM\", length: 42, type: \"primary\" },\n  ],\n};\n\nconst attentionMeter = {\n  length: 100,\n  values: [\n    { label: \"Latency\", length: 64, type: \"warning\" },\n    { label: \"Disk\", length: 51, type: \"help\" },\n  ],\n};\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"status-grid\">\n          <Panel size=\"small\">\n            <template #header><h4>Healthy</h4></template>\n            <div class=\"feedback-card\">\n              <Message color=\"success\" title=\"Stable\">CPU 18% · Memory 1.2 GB</Message>\n              <MeterGroup :meter=\"healthyMeter\" />\n            </div>\n          </Panel>\n          <Panel size=\"small\">\n            <template #header><h4>Attention</h4></template>\n            <div class=\"feedback-card\">\n              <Message color=\"warning\" title=\"Queue rising\">Latency increased.</Message>\n              <MeterGroup :meter=\"attentionMeter\" />\n            </div>\n          </Panel>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"feedback-stack\">\n          <Result title=\"Backup completed\" description=\"Snapshot and metadata have been stored.\" status=\"success\" />\n          <Empty title=\"No running instances\" description=\"Use this state to explain the next meaningful action.\" />\n          <Skeleton :lines=\"3\" height=\"14px\" />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.status-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.feedback-card,\n.feedback-stack {\n  display: grid;\n  gap: 14px;\n}\n\n@media (max-width: 980px) {\n  .status-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/input": "<script setup lang=\"ts\">\nimport { InputNumber, InputText, Panel, Textarea } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst name = ref(\"Future Paper EU-1\");\nconst smallName = ref(\"Small input\");\nconst mediumName = ref(\"Medium input\");\nconst largeName = ref(\"Large input\");\nconst password = ref(\"correct-horse-battery-staple\");\nconst note = ref(\"A quiet resize interaction matters when the user is editing long server notes.\");\nconst command = ref(\"java -Xms2G -Xmx4G -jar server.jar nogui\");\nconst port = ref(25565);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Inputs</h2></template>\n        <div class=\"input-layout\">\n          <label class=\"input-field\">\n            <span>Instance</span>\n            <InputText v-model=\"name\" clearable placeholder=\"Instance name\" />\n          </label>\n          <label class=\"input-field\">\n            <span>Password</span>\n            <InputText v-model=\"password\" password placeholder=\"Password\" />\n          </label>\n          <label class=\"input-field\">\n            <span>Port</span>\n            <InputNumber v-model=\"port\" :min=\"1\" :max=\"65535\" />\n          </label>\n          <label class=\"input-field input-field--wide\">\n            <span>Notes</span>\n            <Textarea v-model=\"note\" placeholder=\"Server notes\" />\n          </label>\n        </div>\n      </Panel>\n\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Sizes</h2></template>\n        <div class=\"sizes-layout\">\n          <label class=\"input-field\">\n            <span>Small</span>\n            <InputText v-model=\"smallName\" size=\"small\" clearable />\n          </label>\n          <label class=\"input-field\">\n            <span>Medium</span>\n            <InputText v-model=\"mediumName\" size=\"medium\" clearable />\n          </label>\n          <label class=\"input-field\">\n            <span>Large</span>\n            <InputText v-model=\"largeName\" size=\"large\" clearable />\n          </label>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Resize Control</h2></template>\n        <div class=\"resize-layout\">\n          <label class=\"input-field\">\n            <span>Resize X</span>\n            <InputText v-model=\"name\" resize-x clearable />\n          </label>\n          <label class=\"input-field\">\n            <span>Resize Y</span>\n            <Textarea v-model=\"command\" resize-y />\n          </label>\n          <label class=\"input-field\">\n            <span>Resize X + Y</span>\n            <Textarea v-model=\"note\" resize-x resize-y />\n          </label>\n          <label class=\"input-field\">\n            <span>Locked</span>\n            <Textarea v-model=\"note\" />\n          </label>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.input-layout,\n.resize-layout,\n.sizes-layout {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 16px;\n  align-items: start;\n}\n\n.resize-layout {\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n}\n\n.sizes-layout {\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  align-items: end;\n}\n\n.input-field {\n  display: grid;\n  min-width: 0;\n  gap: 8px;\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n  font-weight: 600;\n}\n\n.input-field > span {\n  color: inherit;\n  font-size: inherit;\n  font-weight: inherit;\n}\n\n.input-field--wide {\n  grid-column: 1 / -1;\n}\n\n@media (max-width: 960px) {\n  .resize-layout {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .sizes-layout {\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 640px) {\n  .input-layout,\n  .resize-layout,\n  .sizes-layout {\n    grid-template-columns: 1fr;\n    gap: 12px;\n  }\n}\n</style>\n",
  "/components/kbd": "<script setup lang=\"ts\">\nimport { Kbd, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"kbd-row\">\n          <Kbd size=\"small\">Esc</Kbd>\n          <Kbd>Ctrl</Kbd>\n          <Kbd>K</Kbd>\n          <Kbd>Enter</Kbd>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"shortcut-list\">\n          <span><Kbd>Ctrl</Kbd><Kbd>K</Kbd></span>\n          <span>Command palette</span>\n          <span><Kbd>Esc</Kbd></span>\n          <span>Close overlay</span>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.kbd-row,\n.shortcut-list span:first-child,\n.shortcut-list span:nth-child(3) {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  align-items: center;\n}\n\n.shortcut-list {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  gap: 12px 16px;\n  align-items: center;\n  color: var(--mcsl-text-color-regular);\n}\n</style>\n",
  "/components/message": "<script setup lang=\"ts\">\nimport { Button, Message, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"message-grid\">\n          <Message title=\"Instance ready\" color=\"success\" closeable>\n            Paper EU-1 is online and accepting console commands.\n          </Message>\n          <Message title=\"Version drift\" color=\"warning\" closeable>\n            Three plugins were built against an older server API.\n          </Message>\n          <Message title=\"Daemon rejected request\" color=\"danger\" closeable>\n            The selected instance is locked by another operation.\n          </Message>\n          <Message title=\"Queue updated\" color=\"help\" closeable>\n            Backup jobs will run after the current upload finishes.\n          </Message>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"message-grid\">\n          <Message title=\"Borderless surface\" color=\"primary\">\n            Status messages use a quiet tinted background and keep the icon aligned to the text rhythm.\n          </Message>\n          <Message title=\"Outlined surface\" color=\"danger\" variant=\"outlined\">\n            Use the outlined variant when the message sits on a dense or similarly tinted surface.\n          </Message>\n          <Message color=\"surface\" icon=\"fas fa-terminal\" variant=\"soft\">\n            Console output paused while the daemon reconnects.\n            <template #buttons=\"{ close }\">\n              <Button size=\"small\" type=\"text\" @click=\"close\">Dismiss</Button>\n              <Button size=\"small\" type=\"primary\" color=\"primary\">Reconnect</Button>\n            </template>\n          </Message>\n          <Message color=\"help\" icon=\"fas fa-circle-info\" variant=\"text\">\n            Inline messages keep the same spacing model without drawing a container.\n          </Message>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.message-grid {\n  display: grid;\n  gap: 12px;\n}\n</style>\n",
  "/components/modal": "<script setup lang=\"ts\">\nimport { Button, Message, Modal, Panel } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst previewVisible = ref(false);\nconst formVisible = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"overlay-row\">\n          <Button @click=\"previewVisible = true\">Preview</Button>\n          <Button type=\"primary\" color=\"primary\" @click=\"formVisible = true\">Create</Button>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <Button icon=\"fas fa-window-restore\" @click=\"previewVisible = true\">Open Modal</Button>\n        <Modal v-model:visible=\"previewVisible\" header=\"Modal Preview\" max-width=\"520px\">\n          <Message title=\"Paper EU-1\" color=\"help\">\n            Modal surfaces stay focused and short.\n          </Message>\n        </Modal>\n        <Modal v-model:visible=\"formVisible\" header=\"Create Instance\" max-width=\"560px\">\n          <Message title=\"Template selected\" color=\"success\">\n            Paper 1.21.1 with Java 21 runtime.\n          </Message>\n        </Modal>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n</style>\n",
  "/components/nav-tabs": "<script setup lang=\"ts\">\nimport { NavTabs, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst tabs = [\n  { label: \"Details\", icon: \"fas fa-circle-info\" },\n  { label: \"Metrics\", icon: \"fas fa-chart-line\" },\n  { label: \"History\", icon: \"fas fa-clock-rotate-left\" },\n  { label: \"Danger\", icon: \"fas fa-triangle-exclamation\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"tabs-stack\">\n          <NavTabs :tabs=\"tabs\" size=\"small\" />\n          <NavTabs :tabs=\"tabs\" />\n          <NavTabs :tabs=\"tabs\" size=\"large\" color=\"help\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <NavTabs :tabs=\"tabs\" shadow=\"hover\" />\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.tabs-stack {\n  display: grid;\n  gap: 14px;\n  justify-items: start;\n}\n</style>\n",
  "/components/navigation": "<script setup lang=\"ts\">\nimport { Breadcrumbs, NavTabs, Panel, Sidebar } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst crumbs = [\n  { label: \"MCSL Future\", icon: \"fas fa-cube\" },\n  { label: \"Gallery\" },\n  { label: \"Navigation\" },\n];\n\nconst pages = [\n  { label: \"Overview\", description: \"Status\", icon: \"fas fa-gauge\", link: \"/components/navigation\" },\n  { label: \"Instances\", description: \"Fleet\", icon: \"fas fa-server\" },\n  { label: \"Settings\", description: \"Policy\", icon: \"fas fa-gear\" },\n];\n\nconst tabs = [\n  { label: \"Details\", icon: \"fas fa-circle-info\" },\n  { label: \"Metrics\", icon: \"fas fa-chart-line\" },\n  { label: \"History\", icon: \"fas fa-clock-rotate-left\" },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"navigation-stack\">\n          <Breadcrumbs :items=\"crumbs\" />\n          <NavTabs :tabs=\"tabs\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"nav-grid\">\n          <Panel size=\"small\">\n            <template #header><h4>Sidebar</h4></template>\n            <Sidebar :pages=\"pages\" />\n          </Panel>\n          <Panel size=\"small\">\n            <template #header><h4>Top Navigation</h4></template>\n            <div class=\"navigation-stack\">\n              <Breadcrumbs :items=\"crumbs\" />\n              <NavTabs :tabs=\"tabs\" shadow=\"hover\" />\n            </div>\n          </Panel>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.navigation-stack {\n  display: grid;\n  gap: 14px;\n  justify-items: start;\n}\n\n.nav-grid {\n  display: grid;\n  grid-template-columns: minmax(220px, 0.7fr) minmax(0, 1.3fr);\n  gap: 14px;\n}\n\n@media (max-width: 920px) {\n  .nav-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/number-box": "<script setup lang=\"ts\">\nimport { InputNumber, Panel } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst port = ref(25565);\nconst memory = ref(4096);\nconst players = ref(20);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"number-grid\">\n          <InputNumber v-model=\"port\" :min=\"1\" :max=\"65535\" />\n          <InputNumber v-model=\"memory\" :step=\"512\" :min=\"1024\" />\n          <InputNumber v-model=\"players\" size=\"small\" :min=\"1\" :max=\"200\" />\n          <InputNumber v-model=\"players\" disabled />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"number-grid\">\n          <label class=\"field\">\n            <span>Port</span>\n            <InputNumber v-model=\"port\" :min=\"1\" :max=\"65535\" />\n          </label>\n          <label class=\"field\">\n            <span>Memory</span>\n            <InputNumber v-model=\"memory\" :step=\"512\" :min=\"1024\" />\n          </label>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.number-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.field {\n  display: grid;\n  gap: 8px;\n}\n\n.field span {\n  color: var(--mcsl-text-color-secondary);\n  font-size: var(--mcsl-font-size-sm);\n}\n\n@media (max-width: 760px) {\n  .number-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/overlays": "<script setup lang=\"ts\">\nimport { Button, DropdownMenu, Panel, Popover, Tooltip } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst menu = [\n  { label: \"Open settings\", icon: \"fas fa-gear\" },\n  { label: \"Duplicate instance\", icon: \"fas fa-copy\" },\n  { label: \"Archive\", icon: \"fas fa-box-archive\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"overlay-demo\">\n          <DropdownMenu :menu=\"menu\">\n            <template #triggerer=\"{ toggle }\">\n              <Button @click=\"toggle\">Dropdown</Button>\n            </template>\n          </DropdownMenu>\n          <Tooltip content=\"Fast inline hint.\">\n            <template #triggerer=\"{ open, close }\">\n              <Button @mouseenter=\"open\" @mouseleave=\"close\">Tooltip</Button>\n            </template>\n          </Tooltip>\n          <Popover title=\"Inspector\">\n            <template #triggerer=\"{ toggle }\">\n              <Button @click=\"toggle\">Popover</Button>\n            </template>\n            <p class=\"overlay-note\">Compact contextual surface.</p>\n          </Popover>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"overlay-demo\">\n          <DropdownMenu :menu=\"menu\">\n            <template #triggerer=\"{ toggle }\">\n              <Button icon=\"fas fa-ellipsis\" @click=\"toggle\">Open Menu</Button>\n            </template>\n          </DropdownMenu>\n          <Popover title=\"Instance\">\n            <template #triggerer=\"{ toggle }\">\n              <Button icon=\"fas fa-circle-info\" @click=\"toggle\">Inspect</Button>\n            </template>\n            <p class=\"overlay-note\">Paper EU-1 · Online · 12 players</p>\n          </Popover>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-demo {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: center;\n}\n\n.overlay-note {\n  margin: 0;\n  color: var(--mcsl-text-color-regular);\n  line-height: 1.6;\n}\n</style>\n",
  "/components/page-header": "<script setup lang=\"ts\">\nimport { Button, ButtonGroup, PageHeader, Panel } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <PageHeader\n          title=\"Instances\"\n          subtitle=\"Manage server lifecycle, runtime policy, and operational state.\"\n        >\n          <template #actions>\n            <Button type=\"primary\" color=\"primary\" icon=\"fas fa-plus\">Create</Button>\n          </template>\n        </PageHeader>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <PageHeader title=\"Paper EU-1\" subtitle=\"Online · Java 21 · 4 GB memory\">\n          <template #actions>\n            <ButtonGroup>\n              <Button icon=\"fas fa-rotate-right\">Restart</Button>\n              <Button type=\"primary\" color=\"danger\" icon=\"fas fa-stop\">Stop</Button>\n            </ButtonGroup>\n          </template>\n        </PageHeader>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n",
  "/components/pagination": "<script setup lang=\"ts\">\nimport { ItemsPagination, Pagination, Panel } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst shortPage = ref(2);\nconst longPage = ref(8);\nconst itemPage = ref(3);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"pagination-stack\">\n          <Pagination v-model:page=\"shortPage\" :length=\"5\" size=\"small\" />\n          <Pagination v-model:page=\"longPage\" :length=\"16\" />\n          <Pagination v-model:page=\"longPage\" :length=\"128\" size=\"large\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"pagination-stack\">\n          <Pagination v-model:page=\"longPage\" :length=\"16\" />\n          <ItemsPagination v-model:page=\"itemPage\" :item-per-page=\"20\" :total=\"240\" />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.pagination-stack {\n  display: grid;\n  gap: 16px;\n  justify-items: start;\n}\n</style>\n",
  "/components/popover": "<script setup lang=\"ts\">\nimport { Button, Message, Panel, Popover, Tag } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"overlay-row\">\n          <Popover title=\"Inspector\">\n            <template #triggerer=\"{ toggle }\">\n              <Button @click=\"toggle\">Bottom</Button>\n            </template>\n            <Message color=\"help\" variant=\"text\">Compact contextual content.</Message>\n          </Popover>\n          <Popover title=\"Status\" default-pos=\"right\">\n            <template #triggerer=\"{ toggle }\">\n              <Button @click=\"toggle\">Right</Button>\n            </template>\n            <Tag color=\"success\">Online</Tag>\n          </Popover>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <Popover title=\"Inspector\">\n          <template #triggerer=\"{ toggle }\">\n            <Button icon=\"fas fa-magnifying-glass-chart\" @click=\"toggle\">Open Popover</Button>\n          </template>\n          <div class=\"popover-body\">\n            <Tag color=\"success\">Running</Tag>\n            <span>12 players · 41 ms latency</span>\n          </div>\n        </Popover>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row,\n.popover-body {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n  align-items: center;\n}\n\n.popover-body {\n  color: var(--mcsl-text-color-regular);\n}\n</style>\n",
  "/components/progress": "<script setup lang=\"ts\">\nimport { Panel, ProgressBar, Spinner } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"progress-stack\">\n          <ProgressBar :progress=\"64\" status=\"loading\" />\n          <ProgressBar :progress=\"100\" status=\"success\" />\n          <ProgressBar :progress=\"42\" status=\"warning\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"progress-stack\">\n          <ProgressBar variant=\"indeterminate\" status=\"loading\" />\n          <ProgressBar variant=\"circle\" :progress=\"72\" status=\"loading\" />\n          <Spinner label=\"Syncing\" />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.progress-stack {\n  display: grid;\n  gap: 16px;\n}\n</style>\n",
  "/components/radio": "<script setup lang=\"ts\">\nimport { Panel, RadioGroup } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst flavor = ref(\"paper\");\nconst channel = ref(\"stable\");\n\nconst flavorOptions = [\n  { label: \"Paper\", value: \"paper\" },\n  { label: \"Fabric\", value: \"fabric\" },\n  { label: \"NeoForge\", value: \"neoforge\" },\n];\n\nconst channelOptions = [\n  { label: \"Stable\", value: \"stable\" },\n  { label: \"Snapshot\", value: \"snapshot\" },\n  { label: \"Experimental\", value: \"experimental\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"radio-stack\">\n          <RadioGroup v-model=\"flavor\" :options=\"flavorOptions\" size=\"small\" />\n          <RadioGroup v-model=\"flavor\" :options=\"flavorOptions\" />\n          <RadioGroup v-model=\"flavor\" :options=\"flavorOptions\" size=\"large\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"radio-stack\">\n          <RadioGroup v-model=\"flavor\" :options=\"flavorOptions\" />\n          <RadioGroup v-model=\"channel\" :options=\"channelOptions\" />\n          <RadioGroup v-model=\"channel\" :options=\"channelOptions\" disabled />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.radio-stack {\n  display: grid;\n  gap: 16px;\n}\n</style>\n",
  "/components/result": "<script setup lang=\"ts\">\nimport { Button, Panel, Result } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"result-grid\">\n          <Result title=\"Completed\" description=\"Deployment image was published.\" status=\"success\" />\n          <Result title=\"Needs attention\" description=\"Two plugins need review.\" status=\"warning\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <Result\n          title=\"Deployment completed\"\n          description=\"The server image has been rebuilt and published.\"\n          status=\"success\"\n        >\n          <div class=\"result-actions\">\n            <Button type=\"primary\" color=\"primary\">Open Instance</Button>\n            <Button>View Logs</Button>\n          </div>\n        </Result>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.result-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n}\n\n.result-actions {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 10px;\n  margin-top: 12px;\n}\n\n@media (max-width: 860px) {\n  .result-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/select": "<script setup lang=\"ts\">\nimport { Panel, Segmented, Select } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst runtime = ref(\"java21\");\nconst flavor = ref(\"paper\");\nconst region = ref(\"eu\");\nconst features = ref([\"console\", \"backup\"]);\n\nconst runtimeOptions = [\n  { label: \"Java 21\", value: \"java21\", icon: \"fas fa-mug-hot\" },\n  { label: \"Java 17\", value: \"java17\", icon: \"fas fa-mug-saucer\" },\n  { label: \"Java 8\", value: \"java8\", disabled: true },\n];\n\nconst flavorOptions = [\n  { label: \"Paper\", value: \"paper\", icon: \"fas fa-layer-group\" },\n  { label: \"Fabric\", value: \"fabric\", icon: \"fas fa-puzzle-piece\" },\n  { label: \"NeoForge\", value: \"neoforge\", icon: \"fas fa-fire\" },\n];\n\nconst regionOptions = [\n  {\n    group: \"Europe\",\n    options: [\n      { label: \"Frankfurt\", value: \"eu\" },\n      { label: \"London\", value: \"uk\" },\n    ],\n  },\n  {\n    group: \"Asia\",\n    options: [\n      { label: \"Singapore\", value: \"sg\" },\n      { label: \"Tokyo\", value: \"jp\" },\n    ],\n  },\n];\n\nconst featureOptions = [\n  { label: \"Console\", value: \"console\" },\n  { label: \"Backup\", value: \"backup\" },\n  { label: \"Metrics\", value: \"metrics\" },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"select-grid\">\n          <Select v-model=\"runtime\" :options=\"runtimeOptions\" prefix=\"Runtime: \" />\n          <Select v-model=\"region\" :options=\"regionOptions\" placeholder=\"Region\" />\n          <Segmented v-model=\"flavor\" :options=\"flavorOptions\" />\n          <Segmented v-model=\"features\" :options=\"featureOptions\" multiple />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"select-grid\">\n          <Select v-model=\"flavor\" :options=\"flavorOptions\" placeholder=\"Server flavor\" />\n          <Select disabled placeholder=\"Disabled select\" :options=\"runtimeOptions\" />\n          <Segmented v-model=\"flavor\" :options=\"flavorOptions\" />\n          <Segmented v-model=\"features\" :options=\"featureOptions\" multiple nullable />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.select-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n  align-items: start;\n}\n\n@media (max-width: 860px) {\n  .select-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/sidebar": "<script setup lang=\"ts\">\nimport { Panel, Sidebar } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst pages = [\n  { label: \"Overview\", description: \"Status\", icon: \"fas fa-gauge\", link: \"/components/sidebar\" },\n  { label: \"Instances\", description: \"Fleet\", icon: \"fas fa-server\" },\n  { label: \"Backups\", description: \"Jobs\", icon: \"fas fa-clock-rotate-left\" },\n  { label: \"Settings\", description: \"Policy\", icon: \"fas fa-gear\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"sidebar-grid\">\n          <Panel size=\"small\">\n            <template #header><h4>Expanded</h4></template>\n            <Sidebar :pages=\"pages\" />\n          </Panel>\n          <Panel size=\"small\" class=\"collapsed-card\">\n            <template #header><h4>Collapsed</h4></template>\n            <Sidebar :pages=\"pages\" collapsed />\n          </Panel>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <Sidebar :pages=\"pages\" />\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.sidebar-grid {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 96px;\n  gap: 14px;\n  align-items: start;\n}\n\n.collapsed-card {\n  justify-self: start;\n  width: 78px;\n}\n\n@media (max-width: 760px) {\n  .sidebar-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/skeleton": "<script setup lang=\"ts\">\nimport { Avatar, Panel, Skeleton } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"skeleton-stack\">\n          <Skeleton :lines=\"3\" height=\"14px\" />\n          <Skeleton width=\"64%\" height=\"16px\" />\n          <Skeleton width=\"36%\" height=\"28px\" :rounded=\"false\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"skeleton-card\">\n          <Avatar text=\"LD\" />\n          <div>\n            <Skeleton width=\"44%\" height=\"15px\" />\n            <Skeleton :lines=\"3\" height=\"12px\" />\n          </div>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.skeleton-stack {\n  display: grid;\n  gap: 12px;\n}\n\n.skeleton-card {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  gap: 14px;\n  align-items: start;\n}\n</style>\n",
  "/components/slider": "<script setup lang=\"ts\">\nimport { Panel, Slider } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst memory = ref(36);\nconst cpu = ref(72);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"slider-stack\">\n          <Slider v-model=\"memory\" :min=\"0\" :max=\"100\" />\n          <Slider v-model=\"cpu\" :min=\"0\" :max=\"100\" :step=\"4\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"slider-stack\">\n          <Slider v-model=\"memory\" :min=\"0\" :max=\"100\" />\n          <Slider v-model=\"cpu\" :min=\"0\" :max=\"100\" disabled />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.slider-stack {\n  display: grid;\n  gap: 18px;\n}\n</style>\n",
  "/components/steps": "<script setup lang=\"ts\">\nimport { Message, Panel, Steps } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst current = ref(1);\n\nconst installSteps = [\n  { title: \"Profile\", description: \"Select loader and version\" },\n  { title: \"Resources\", description: \"Allocate memory and ports\" },\n  { title: \"Review\", description: \"Confirm launch settings\" },\n  { title: \"Launch\", description: \"Start the instance\" },\n];\n\nconst taskSteps = [\n  { title: \"Queued\", description: \"Waiting for daemon slot\" },\n  { title: \"Downloading\", description: \"Fetching server artifacts\" },\n  { title: \"Verify\", description: \"Hash and metadata checks\", status: \"error\" as const },\n  { title: \"Done\", description: \"Ready to launch\", disabled: true },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Steps</h2></template>\n        <div class=\"steps-stack\">\n          <Steps v-model=\"current\" :items=\"installSteps\" clickable />\n          <Steps :items=\"installSteps\" :model-value=\"2\" size=\"small\" color=\"success\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>安装流程</h2></template>\n        <div class=\"steps-demo\">\n          <Steps v-model=\"current\" :items=\"installSteps\" clickable color=\"primary\" />\n          <Message color=\"help\" title=\"Selected step\">\n            {{ installSteps[current]?.title }} - {{ installSteps[current]?.description }}\n          </Message>\n          <Steps :items=\"taskSteps\" :model-value=\"1\" vertical color=\"warning\" />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.steps-stack,\n.steps-demo {\n  display: grid;\n  gap: 18px;\n}\n</style>\n",
  "/components/table": "<script setup lang=\"ts\">\nimport { Panel, Table } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst columns = [\"Name\", \"Status\", \"Version\", \"Players\"];\nconst rows = [\n  [\"Paper EU-1\", \"Running\", \"1.21.1\", 12],\n  [\"Fabric Dev\", \"Stopped\", \"1.20.4\", 0],\n  [\"Velocity Edge\", \"Starting\", \"3.4.0\", 48],\n];\n\nconst denseRows = [\n  [\"CPU\", \"18%\", \"Normal\"],\n  [\"Memory\", \"4.1 GB\", \"Normal\"],\n  [\"Disk\", \"72%\", \"Warning\"],\n  [\"Network\", \"41 ms\", \"Normal\"],\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <Table :columns=\"columns\" :rows=\"rows\" />\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"table-stack\">\n          <Table :columns=\"columns\" :rows=\"rows\" />\n          <Table :columns=\"['Metric', 'Value', 'State']\" :rows=\"denseRows\" />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.table-stack {\n  display: grid;\n  gap: 16px;\n}\n</style>\n",
  "/components/tag": "<script setup lang=\"ts\">\nimport { Badge, Button, Panel, Tag } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"tag-row\">\n          <Tag color=\"surface\">Surface</Tag>\n          <Tag color=\"primary\">Primary</Tag>\n          <Tag color=\"success\">Healthy</Tag>\n          <Tag color=\"warning\">Warning</Tag>\n          <Tag color=\"danger\">Danger</Tag>\n          <Tag color=\"help\">Help</Tag>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"tag-row\">\n          <Badge value=\"8\" color=\"danger\">\n            <Button icon=\"fas fa-bell\">Notifications</Button>\n          </Badge>\n          <Tag color=\"success\">Running</Tag>\n          <Tag color=\"primary\">Java 21</Tag>\n          <Tag color=\"help\">Paper</Tag>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.tag-row {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n  align-items: center;\n}\n</style>\n",
  "/components/toggle": "<script setup lang=\"ts\">\nimport { Panel, Switch } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst autoStart = ref(false);\nconst maintenance = ref(true);\nconst metrics = ref(true);\nconst locked = ref(false);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"toggle-grid\">\n          <label class=\"toggle-row\">\n            <Switch v-model=\"autoStart\" size=\"small\" />\n            <span>Small</span>\n          </label>\n          <label class=\"toggle-row\">\n            <Switch v-model=\"maintenance\" color=\"warning\" />\n            <span>Warning</span>\n          </label>\n          <label class=\"toggle-row\">\n            <Switch v-model=\"metrics\" color=\"success\" size=\"large\" />\n            <span>Large</span>\n          </label>\n          <label class=\"toggle-row\">\n            <Switch v-model=\"locked\" disabled />\n            <span>Disabled</span>\n          </label>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"toggle-stack\">\n          <label class=\"toggle-row\">\n            <Switch v-model=\"autoStart\" />\n            <span>Auto-start daemon</span>\n          </label>\n          <label class=\"toggle-row\">\n            <Switch v-model=\"maintenance\" color=\"warning\" />\n            <span>Maintenance mode</span>\n          </label>\n          <label class=\"toggle-row\">\n            <Switch v-model=\"metrics\" color=\"success\" />\n            <span>Collect metrics</span>\n          </label>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.toggle-grid,\n.toggle-stack {\n  display: grid;\n  gap: 14px;\n}\n\n.toggle-grid {\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n}\n\n.toggle-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  color: var(--mcsl-text-color-regular);\n}\n\n@media (max-width: 720px) {\n  .toggle-grid {\n    grid-template-columns: 1fr;\n  }\n}\n</style>\n",
  "/components/tooltip": "<script setup lang=\"ts\">\nimport { Button, Panel, Tooltip } from \"@mcsl/ui\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"overlay-row\">\n          <Tooltip content=\"Start the selected instance.\">\n            <template #triggerer=\"{ open, close }\">\n              <Button @mouseenter=\"open\" @mouseleave=\"close\">Top</Button>\n            </template>\n          </Tooltip>\n          <Tooltip content=\"Opens in a side panel.\" default-pos=\"right\">\n            <template #triggerer=\"{ open, close }\">\n              <Button @mouseenter=\"open\" @mouseleave=\"close\">Right</Button>\n            </template>\n          </Tooltip>\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <Tooltip content=\"Helpful detail for this action.\">\n          <template #triggerer=\"{ open, close }\">\n            <Button icon=\"fas fa-circle-info\" @mouseenter=\"open\" @mouseleave=\"close\">\n              Hover me\n            </Button>\n          </template>\n        </Tooltip>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.overlay-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n</style>\n",
  "/components/tree": "<script setup lang=\"ts\">\nimport { Message, Panel, Tree, TreeSelect } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst expandedKeys = ref([\"instances\", \"configs\"]);\nconst selectedKeys = ref([\"paper-eu\"]);\nconst selectedFile = ref(\"server-properties\");\n\nconst treeItems = [\n  {\n    key: \"instances\",\n    label: \"Instances\",\n    icon: \"fas fa-server\",\n    children: [\n      { key: \"paper-eu\", label: \"Paper EU-1\", icon: \"fas fa-cube\" },\n      { key: \"forge-us\", label: \"Forge US-2\", icon: \"fas fa-cube\" },\n    ],\n  },\n  {\n    key: \"configs\",\n    label: \"Configs\",\n    icon: \"fas fa-folder\",\n    children: [\n      { key: \"server-properties\", label: \"server.properties\", icon: \"fas fa-file-lines\" },\n      { key: \"permissions\", label: \"permissions.yml\", icon: \"fas fa-file-code\" },\n      { key: \"locked\", label: \"locked.yml\", icon: \"fas fa-lock\", disabled: true },\n    ],\n  },\n  {\n    key: \"backups\",\n    label: \"Backups\",\n    icon: \"fas fa-box-archive\",\n    children: [\n      { key: \"daily\", label: \"Daily snapshots\", icon: \"fas fa-clock\" },\n      { key: \"manual\", label: \"Manual exports\", icon: \"fas fa-download\" },\n    ],\n  },\n];\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>Tree</h2></template>\n        <Tree\n          v-model:expanded-keys=\"expandedKeys\"\n          v-model:selected-keys=\"selectedKeys\"\n          :items=\"treeItems\"\n        />\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>树选择器</h2></template>\n        <div class=\"tree-stack\">\n          <TreeSelect v-model=\"selectedFile\" :items=\"treeItems\" placeholder=\"Choose file\" />\n          <Message color=\"help\" title=\"Selected key\">{{ selectedFile }}</Message>\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.tree-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
  "/components/upload": "<script setup lang=\"ts\">\nimport { FileDropper, FileInfo, Message, Panel } from \"@mcsl/ui\";\nimport { ref } from \"vue\";\nimport GalleryDocPage from \"../components/GalleryDocPage.vue\";\n\nconst files = ref<File[]>([]);\n</script>\n\n<template>\n  <GalleryDocPage>\n    <template #effects>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>基础</h2></template>\n        <div class=\"upload-stack\">\n          <Message title=\"Upload policy\" color=\"help\">\n            Up to five files are accepted in this gallery sample.\n          </Message>\n          <FileDropper v-model=\"files\" :config=\"{ maxCount: 5 }\" :file-info=\"false\" />\n        </div>\n      </Panel>\n    </template>\n\n    <template #demo>\n      <Panel class=\"doc-section\" shadow=\"hover\">\n        <template #header><h2>示例</h2></template>\n        <div class=\"upload-stack\">\n          <FileDropper v-model=\"files\" :config=\"{ maxCount: 5 }\" />\n          <FileInfo v-model=\"files\" />\n        </div>\n      </Panel>\n    </template>\n  </GalleryDocPage>\n</template>\n\n<style scoped lang=\"scss\">\n.upload-stack {\n  display: grid;\n  gap: 14px;\n}\n</style>\n",
};
